class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

    def __eq__(self, other):
        if not isinstance(other, Node):
            return NotImplemented
        return (self.value == other.value and
                self.left == other.left and
                self.right == other.right)

    def __repr__(self):
        return f"Node({self.value!r}, {self.left!r}, {self.right!r})"


class ParentContext:
    def __init__(self, value, sibling, direction, parent_context):
        self.value = value  # value of the direct parent node
        # The sibling of the currently focused node.
        # If focus was the left child, this is the parent's right child.
        # If focus was the right child, this is the parent's left child.
        self.sibling = sibling
        # 'L' if focus was the left child of this parent, 'R' if it was the right child.
        self.direction = direction
        self.parent_context = parent_context  # The context of the parent's parent (further up the tree)

    def __eq__(self, other):
        if not isinstance(other, ParentContext):
            return NotImplemented
        return (self.value == other.value and
                self.sibling == other.sibling and
                self.direction == other.direction and
                self.parent_context == other.parent_context)

    def __repr__(self):
        return (f"ParentContext(value={self.value!r}, sibling={self.sibling!r}, "
                f"direction={self.direction!r}, parent_context={self.parent_context!r})")


class Zipper:
    def __init__(self, focus_node, context_stack):
        self._focus = focus_node
        self._context = context_stack  # The top-most ParentContext or None if at root

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, None)

    def value(self):
        return self._focus.value

    def set_value(self, new_value):
        # Creates a new zipper with the focus node's value changed
        new_focus = Node(new_value, self._focus.left, self._focus.right)
        return Zipper(new_focus, self._context)

    def left(self):
        # Move focus to the left child of the current focus node
        if not self._focus.left:
            return None  # Cannot move left if there's no left child

        # Create new context item for the current focus node (which becomes the parent)
        new_context_item = ParentContext(
            value=self._focus.value,
            sibling=self._focus.right,  # The right child becomes the sibling
            direction='L',              # We moved to the left
            parent_context=self._context
        )
        return Zipper(self._focus.left, new_context_item)

    def set_left(self, new_left):
        # Returns a new zipper with the focus node's left child updated
        new_focus = Node(self._focus.value, new_left, self._focus.right)
        return Zipper(new_focus, self._context)

    def right(self):
        # Move focus to the right child of the current focus node
        if not self._focus.right:
            return None  # Cannot move right if there's no right child

        # Create new context item for the current focus node (which becomes the parent)
        new_context_item = ParentContext(
            value=self._focus.value,
            sibling=self._focus.left,  # The left child becomes the sibling
            direction='R',             # We moved to the right
            parent_context=self._context
        )
        return Zipper(self._focus.right, new_context_item)

    def set_right(self, new_right):
        # Returns a new zipper with the focus node's right child updated
        new_focus = Node(self._focus.value, self._focus.left, new_right)
        return Zipper(new_focus, self._context)

    def up(self):
        # Move focus to the parent of the current focus node
        if not self._context:
            return None  # Already at the root, no parent

        parent_ctx = self._context

        # Reconstruct the parent node based on the context
        if parent_ctx.direction == 'L':
            # Current focus was the left child of its parent
            reconstructed_parent = Node(
                value=parent_ctx.value,
                left=self._focus,          # Current focus is the parent's left child
                right=parent_ctx.sibling    # Sibling stored in context is parent's right child
            )
        else:  # parent_ctx.direction == 'R'
            # Current focus was the right child of its parent
            reconstructed_parent = Node(
                value=parent_ctx.value,
                left=parent_ctx.sibling,    # Sibling stored in context is parent's left child
                right=self._focus           # Current focus is the parent's right child
            )

        # The new focus is the reconstructed parent, and its context is the grandparent's context
        return Zipper(reconstructed_parent, parent_ctx.parent_context)

    def to_tree(self):
        # Climb up the tree until the root is reached and return the reconstructed tree
        current_zipper = self
        while current_zipper._context:
            current_zipper = current_zipper.up()
        return current_zipper._focus
